import Image from 'next/image'

import { ExpandableTextBox } from '@/components/library/feedback/ExpandableTextBox'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type FloatingMediaArticleProps = {
  title: string
  image: { src: string; alt: string }
  paragraphs: readonly string[]
  eyebrow?: string
  caption?: string
  imagePosition?: 'left' | 'right'
  more?: { paragraphs: readonly string[]; collapsedLabel?: string; expandedLabel?: string }
  tone?: AccentTone
  className?: string
}

/** Artigo editorial com figura flutuante contornada pelo texto e bloco "leia mais" opcional. */
export function FloatingMediaArticle({
  title,
  image,
  paragraphs,
  eyebrow,
  caption,
  imagePosition = 'right',
  more,
  tone = 'glow',
  className,
}: FloatingMediaArticleProps) {
  const t = getAccentTone(tone)

  return (
    <section className={cn(t.section, className)}>
      <div className="container py-14 lg:py-16">
        <EyebrowHeading tone={tone} eyebrow={eyebrow} title={title} />

        <div className="mt-8">
          <figure
            className={cn(
              'relative mb-5 w-full overflow-hidden border sm:w-[46%] lg:w-[42%]',
              imagePosition === 'right'
                ? 'sm:float-right sm:ml-8 lg:ml-10'
                : 'sm:float-left sm:mr-8 lg:mr-10',
              t.border,
              tone === 'glow' && 'rounded-xl',
            )}
          >
            <div className={cn('relative aspect-[4/3] w-full', t.panel)}>
              <Image
                src={image.src}
                alt={image.alt}
                fill
                sizes="(max-width: 640px) 100vw, 46vw"
                className="object-cover"
              />
            </div>
            {caption ? (
              <figcaption
                className={cn(
                  'border-t px-4 py-3 text-[0.65rem] uppercase tracking-[0.2em]',
                  t.border,
                  t.panel,
                  t.muted,
                )}
              >
                {caption}
              </figcaption>
            ) : null}
          </figure>

          {paragraphs.map((paragraph, index) => (
            <p
              key={index}
              className={cn('mb-4 text-base leading-relaxed sm:text-[1.05rem]', t.body)}
            >
              {paragraph}
            </p>
          ))}

          <div className="clear-both" />

          {more ? (
            <ExpandableTextBox
              tone={tone}
              paragraphs={more.paragraphs}
              collapsedLabel={more.collapsedLabel}
              expandedLabel={more.expandedLabel}
              className="mt-8"
            />
          ) : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useId, useState } from 'react'
import { ChevronDown } from 'lucide-react'

import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type ExpandableTextBoxProps = {
  paragraphs: readonly string[]
  collapsedLabel?: string
  expandedLabel?: string
  defaultOpen?: boolean
  tone?: AccentTone
  className?: string
}

/** Caixa "leia mais" que expande parágrafos extras com transição de altura. */
export function ExpandableTextBox({
  paragraphs,
  collapsedLabel = 'Ler mais',
  expandedLabel = 'Mostrar menos',
  defaultOpen = false,
  tone = 'glow',
  className,
}: ExpandableTextBoxProps) {
  const t = getAccentTone(tone)
  const [open, setOpen] = useState(defaultOpen)
  const panelId = useId()

  return (
    <div className={cn('border', t.border, t.panel, tone === 'glow' && 'rounded-md', className)}>
      <button
        type="button"
        onClick={() => setOpen((value) => !value)}
        className={cn(
          'flex w-full items-center justify-between gap-4 px-5 py-4 text-left transition-colors sm:px-6',
          t.panelHover,
          t.focus,
        )}
        aria-expanded={open}
        aria-controls={panelId}
      >
        <span className={cn('text-sm font-semibold tracking-wide', t.strong)}>
          {open ? expandedLabel : collapsedLabel}
        </span>
        <ChevronDown
          className={cn(
            'h-5 w-5 shrink-0 transition-transform duration-300',
            t.accent,
            open && 'rotate-180',
          )}
          aria-hidden
        />
      </button>
      <div
        id={panelId}
        className={cn(
          'grid transition-all duration-500 ease-out',
          open ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0',
        )}
      >
        <div className="overflow-hidden" aria-hidden={!open}>
          <div
            className={cn(
              'space-y-4 border-t px-5 py-5 text-sm leading-relaxed sm:px-6 sm:py-6 sm:text-base',
              t.border,
              t.body,
            )}
          >
            {paragraphs.map((paragraph, index) => (
              <p key={index}>{paragraph}</p>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}

import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'

import { getAccentTone, type AccentTone } from './accentTones'

export type EyebrowHeadingProps = {
  title: ReactNode
  eyebrow?: ReactNode
  description?: ReactNode
  tone?: AccentTone
  align?: 'left' | 'center'
  layout?: 'stacked' | 'split'
  size?: 'md' | 'lg'
  titleAs?: 'h1' | 'h2' | 'h3'
  action?: ReactNode
  className?: string
}

const titleSizes = {
  md: 'text-3xl leading-[1.15] sm:text-4xl lg:text-[2.5rem]',
  lg: 'text-3xl leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
}

/** Cabeçalho de seção com linha de destaque, título temático e descrição opcional ao lado. */
export function EyebrowHeading({
  title,
  eyebrow,
  description,
  tone = 'glow',
  align = 'left',
  layout = 'stacked',
  size = 'md',
  titleAs: Title = 'h2',
  action,
  className,
}: EyebrowHeadingProps) {
  const t = getAccentTone(tone)
  const centered = align === 'center'
  const split = layout === 'split' && !centered

  const line = <span className={cn('h-px w-8 shrink-0', t.line)} aria-hidden />

  return (
    <div
      className={cn(
        split && 'flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between',
        centered && 'mx-auto max-w-3xl text-center',
        className,
      )}
    >
      <div className={cn(split ? 'max-w-2xl' : centered ? '' : 'max-w-3xl')}>
        {eyebrow ? (
          <div className={cn('mb-4 flex items-center gap-3', centered && 'justify-center')}>
            {line}
            <span
              className={cn('text-[0.65rem] font-medium uppercase tracking-[0.28em]', t.accent)}
            >
              {eyebrow}
            </span>
            {centered ? line : null}
          </div>
        ) : null}
        <Title className={cn(t.heading, titleSizes[size], centered && 'mx-auto')}>{title}</Title>
        {!split && description ? (
          <p
            className={cn(
              'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
              t.body,
              centered && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
        {!split && action ? (
          <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
            {action}
          </div>
        ) : null}
      </div>
      {split && (description || action) ? (
        <div className="max-w-md space-y-5">
          {description ? (
            <p className={cn('text-sm leading-relaxed lg:text-base', t.body)}>{description}</p>
          ) : null}
          {action}
        </div>
      ) : null}
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
